    fr: 'À chaque transaction dans Arkana, 33 % des $SKR sont brûlés à jamais, 33 % vont à la trésorerie d\'Arkana et 34 % alimentent le rendement du staking sur 365 jours du Coffre sacré $ORE.',
    zh: 'Arkana 的每一笔交易中，33% 的 $SKR 永久销毁，33% 进入 Arkana 国库，34% 注入 $ORE 神圣金库的 365 天质押收益流。',
    hi: 'Arkana में हर ट्रांज़ैक्शन पर 33% $SKR हमेशा के लिए बर्न होता है, 33% Arkana ट्रेज़री में जाता है और 34% $ORE पवित्र वॉल्ट की 365 दिन की स्टेकिंग यील्ड में जाता है।',
    ar: 'مع كل معاملة في Arkana، تُحرق 33% من $SKR إلى الأبد، وتُخصَّص 33% لخزينة Arkana، وتتجه 34% إلى عوائد staking لمدة 365 يومًا في خزنة $ORE المقدسة.',
