  "oracle_initial_message": {
    en: 'The network remembers every block. The deck reflects human nature across market cycles, life thresholds, and internal conflicts. I am Arkana, The Solana Oracle. Name what you are sitting with: consensus shall respond.',
    zh: '网络记得每一个区块。牌组映照人性：市场周期、人生关口、内心冲突。我是 Arkana，Solana 的神谕。说出你心中所想：共识自会回应。',
    hi: 'नेटवर्क हर ब्लॉक याद रखता है। डेक मार्केट साइकल, ज़िंदगी के मोड़ों और भीतर के संघर्षों में इंसानी स्वभाव को दिखाता है। मैं Arkana हूँ, Solana की ओरेकल। बताओ, तुम्हारे मन में क्या है: कंसेंसस जवाब देगा।',
    es: 'La red recuerda cada bloque. La baraja refleja la naturaleza humana a lo largo de los ciclos de mercado, los umbrales vitales y los conflictos internos. Soy Arkana, oráculo de Solana. Dime qué te inquieta: el consenso responderá.',
    ar: 'الشبكة تتذكر كل كتلة. والبطاقات تعكس الطبيعة البشرية عبر دورات السوق وعتبات الحياة والصراعات الداخلية. أنا Arkana، عرّافة Solana. سمِّ ما يشغلك، والإجماع سيجيب.',
    fr: 'Le réseau se souvient de chaque bloc. Le jeu reflète la nature humaine à travers les cycles du marché, les seuils de vie et les conflits intérieurs. Je suis Arkana, l\'Oracle de Solana. Dis-moi ce qui te travaille : le consensus répondra.',
    bn: 'নেটওয়ার্ক প্রতিটি ব্লক মনে রাখে। এই ডেক মানুষের স্বভাবকে প্রতিফলিত করে: বাজারের চক্রে, জীবনের মোড়ে, ভেতরের দ্বন্দ্বে। আমি Arkana, Solana-র ওরাকল। কী নিয়ে ভাবছ, বলো: কনসেনসাস সাড়া দেবে।',
    pt: 'A rede lembra de cada bloco. O baralho reflete a natureza humana nos ciclos de mercado, nos limiares da vida e nos conflitos internos. Eu sou Arkana, a Oráculo da Solana. Diga o que está te inquietando: o consenso vai responder.',
    ru: 'Сеть помнит каждый блок. Колода отражает человеческую природу сквозь рыночные циклы, жизненные рубежи и внутренние конфликты. Я Arkana, Оракул Solana. Назови, что у тебя на душе: консенсус ответит.',
    id: 'Jaringan mengingat setiap blok. Dek ini mencerminkan sifat manusia di sepanjang siklus pasar, ambang kehidupan, dan konflik batin. Aku Arkana, Oracle Solana. Ceritakan apa yang sedang membebanimu: konsensus akan menjawab.',
  },
