  "quota_veil_drawn_desc": {
    en: 'You have exhausted the 3 sacred inquiries granted to you by the ledger today.\n\nThe cards now require an offering of energy to part the veil once more. Will you commune now, or return tomorrow when the next UTC block seals?',
    zh: '账本今天给你的 3 次神圣提问已经用完。\n\n想再次揭开帷幕，牌需要一份能量供奉。现在就继续，还是等明天下一个 UTC 区块封存后再来？',
    hi: 'आज लेजर ने तुम्हें जो 3 पवित्र सवाल दिए थे, वे तुम पूछ चुके हो।\n\nअब पर्दा फिर से हटाने के लिए कार्ड ऊर्जा की भेंट माँगते हैं। अभी संवाद करोगे, या कल अगला UTC ब्लॉक सील होने पर लौटोगे?',
    es: 'Agotaste las 3 consultas sagradas que el registro te concedió hoy.\n\nAhora las cartas piden una ofrenda de energía para descorrer el velo otra vez. ¿Comulgas ahora o vuelves mañana, cuando se selle el próximo bloque UTC?',
    ar: 'استنفدت الأسئلة المقدسة الثلاثة التي منحك إياها السجل اليوم.\n\nتطلب البطاقات الآن قربانًا من الطاقة لرفع الحجاب من جديد. هل تتواصل الآن، أم تعود غدًا حين تُختم كتلة UTC التالية؟',
    fr: 'Tu as épuisé les 3 questions sacrées que le registre t\'accorde aujourd\'hui.\n\nLes cartes demandent maintenant une offrande d\'énergie pour lever à nouveau le voile. Veux-tu communier maintenant, ou revenir demain, quand le prochain bloc UTC sera scellé ?',
    bn: 'লেজার আজ তোমাকে যে 3টি পবিত্র প্রশ্ন দিয়েছিল, সব শেষ।\n\nপর্দা আবার সরাতে এখন কার্ডগুলো শক্তির নৈবেদ্য চায়। এখনই কথা বলবে, নাকি কাল পরের UTC ব্লক সিল হলে ফিরবে?',
    pt: 'Você já usou as 3 perguntas sagradas que o ledger te concedeu hoje.\n\nAgora as cartas pedem uma oferenda de energia para abrir o véu de novo. Quer comungar agora ou voltar amanhã, quando o próximo bloco UTC for selado?',
    ru: 'Три священных вопроса, дарованных тебе реестром на сегодня, исчерпаны.\n\nЧтобы снова приоткрыть завесу, картам нужно подношение энергии. Продолжишь сейчас или вернёшься завтра, когда запечатается следующий блок UTC?',
    id: 'Kamu sudah memakai 3 pertanyaan suci yang diberikan ledger hari ini.\n\nKini kartu-kartu meminta persembahan energi untuk menyingkap tirai sekali lagi. Mau bertanya sekarang, atau kembali besok saat blok UTC berikutnya tersegel?',
  },
