    ar: 'السرعة العاطفية في المعاملات ورسوم الأولوية المسعّرة خطأً تقود إلى تفرعات كان يمكن تجنبها.',
    fr: 'Trader au rythme des émotions et mal évaluer les frais de priorité mènent à des forks évitables.',
    bn: 'আবেগে তাড়াহুড়োর লেনদেন আর ভুল দামের প্রায়োরিটি ফি এমন ফর্ক ডেকে আনে যা এড়ানো যেত।',
    pt: 'Operar no ritmo das emoções e errar nas taxas de prioridade leva a forks que poderiam ser evitados.',
    ru: 'Эмоциональная скорость сделок и неверно оценённые приоритетные комиссии ведут к форкам, которых можно было избежать.',
