    hi: 'शून्य ट्रांज़ैक्शन इतिहास। पूरी तरह खुली, संप्रभु संभावना।\n\nSeeker वेदी पर निकला: The New Wallet ({o}).\n\n"{quote}"\n\nदिन {streak} की कंसेंसस. हर लेजेंड की शुरुआत एक ख़ाली एड्रेस से हुई थी।\n#Solana #ArkanaTarot #Seeker #ClockIn',
    es: 'Cero historial de transacciones. Potencial soberano sin asignar.\n\nSalió en el Altar de Seeker: The New Wallet ({o}).\n\n"{quote}"\n\nConsenso del día {streak}. Toda leyenda empezó con una dirección vacía.\n#Solana #ArkanaTarot #Seeker #ClockIn',
