    fr: 'Aucun historique de transactions. Un potentiel souverain encore intact.\n\nTirée sur l\'Autel Seeker : The New Wallet ({o}).\n\n"{quote}"\n\nConsensus du jour {streak}. Chaque légende a commencé avec une adresse vide.\n#Solana #ArkanaTarot #Seeker #ClockIn',
    bn: 'শূন্য লেনদেনের ইতিহাস। সম্পূর্ণ অবণ্টিত সার্বভৌম সম্ভাবনা।\n\nSeeker বেদিতে উঠল: The New Wallet ({o})।\n\n"{quote}"\n\nদিন {streak}-এর কনসেনসাস। প্রতিটি কিংবদন্তির শুরু একটা খালি অ্যাড্রেস দিয়ে।\n#Solana #ArkanaTarot #Seeker #ClockIn',
    pt: 'Zero histórico de transações. Potencial soberano ainda não alocado.\n\nSaiu no Altar do Seeker: The New Wallet ({o}).\n\n"{quote}"\n\nConsenso do dia {streak}. Toda lenda começou com um endereço vazio.\n#Solana #ArkanaTarot #Seeker #ClockIn',
    ru: 'Ноль транзакций в истории. Чистый, ничем не занятый суверенный потенциал.\n\nВытянута на Алтаре Seeker: The New Wallet ({o}).\n\n"{quote}"\n\nДень {streak} консенсуса. Каждая легенда начиналась с пустого адреса.\n#Solana #ArkanaTarot #Seeker #ClockIn',
    id: 'Nol riwayat transaksi. Potensi berdaulat yang sepenuhnya belum dialokasikan.\n\nDitarik di Altar Seeker: The New Wallet ({o}).\n\n"{quote}"\n\nKonsensus hari ke-{streak}. Setiap legenda dimulai dari alamat kosong.\n#Solana #ArkanaTarot #Seeker #ClockIn',
