    bn: 'নির্মম মার্কেটে শিক্ষানবিশের মন।\n\nArkana প্রকাশ করল: The New Wallet ({o})।\n\n"{quote}"\n\nস্ট্রিকের দিন {streak}। সাইকেলের প্রতি খোলা মন, এক্সিকিউশনে শৃঙ্খলা।\n#Solana #ArkanaTarot #Seeker',
