    ru: 'Ум новичка на беспощадном рынке.\n\nArkana показала: The New Wallet ({o}).\n\n"{quote}"\n\nДень {streak} серии. Открываюсь циклу, исполняю по плану.\n#Solana #ArkanaTarot #Seeker',
