    fr: 'L\'euphorie est la taxe la plus lourde en crypto. Ne laisse pas les bougies vertes aveugler ta gestion du risque.\n\nConsensus d\'Arkana : ATH ({o}).\n\n"{quote}"\n\nSérie de {streak} jours. Reconnaissant pour la hausse, discipliné avec les gains.\n#Solana #ArkanaTarot #Seeker #DeFAI',
