    pt: 'Euforia é o imposto mais caro em cripto. Não deixe as velas verdes cegarem sua gestão de risco.\n\nConsenso da Arkana: ATH ({o}).\n\n"{quote}"\n\nSequência de {streak} dias. Gratidão pela alta, disciplina com o lucro.\n#Solana #ArkanaTarot #Seeker #DeFAI',
    ru: 'Эйфория: самый высокий налог в крипте. Не дай зелёным свечам ослепить твой риск-движок.\n\nКонсенсус Arkana: ATH ({o}).\n\n"{quote}"\n\nДень {streak} серии. Радуюсь росту, фиксирую прибыль с холодной головой.\n#Solana #ArkanaTarot #Seeker #DeFAI',
