    es: 'Nunca eres tan listo como te sientes en un bull run, ni estás tan acabado como te sientes en un bear.\n\nAncla de Arkana: Market Cycle ({o}).\n\n"{quote}"\n\nRacha de {streak} días. Surfeando la rotación con calma de validador.\n#Solana #ArkanaTarot #Seeker',
    ar: 'لست أبدًا بالذكاء الذي تشعر به في السوق الصاعدة، ولا بالانهيار الذي تشعر به في الهابطة.\n\nمرساة Arkana: Market Cycle ({o}).\n\n"{quote}"\n\nاليوم {streak} من السلسلة. أركب التدوير بهدوء المدقق.\n#Solana #ArkanaTarot #Seeker',
    fr: 'Tu n\'es jamais aussi malin que tu le crois en bull run, ni aussi fini que tu le crois en bear.\n\nAncre d\'Arkana : Market Cycle ({o}).\n\n"{quote}"\n\nSérie de {streak} jours. Je surfe la rotation avec un calme de validateur.\n#Solana #ArkanaTarot #Seeker',
    bn: 'বুল রানে তুমি নিজেকে যতটা স্মার্ট ভাবো ততটা নও, আর বিয়ারে যতটা শেষ ভাবো ততটাও নও।\n\nArkana-র নোঙর: Market Cycle ({o})।\n\n"{quote}"\n\nস্ট্রিকের দিন {streak}। ভ্যালিডেটরের ধীরতায় রোটেশনে চড়ছি।\n#Solana #ArkanaTarot #Seeker',
    pt: 'Você nunca é tão genial quanto se sente no bull run, nem tão acabado quanto se sente no bear.\n\nÂncora da Arkana: Market Cycle ({o}).\n\n"{quote}"\n\nSequência de {streak} dias. Surfando a rotação com calma de validador.\n#Solana #ArkanaTarot #Seeker',
    ru: 'На бычке ты никогда не так умён, как кажется, а на медведе никогда не так разбит, как кажется.\n\nЯкорь Arkana: Market Cycle ({o}).\n\n"{quote}"\n\nДень {streak} серии. Ловлю ротацию со спокойствием валидатора.\n#Solana #ArkanaTarot #Seeker',
    id: 'Kamu tak pernah sepintar yang kamu rasa saat bull run, dan tak pernah sehancur yang kamu rasa saat bear.\n\nJangkar Arkana: Market Cycle ({o}).\n\n"{quote}"\n\nStreak hari ke-{streak}. Mengikuti rotasi dengan ketenangan validator.\n#Solana #ArkanaTarot #Seeker',
