    fr: 'En DeFi, l\'alignement est tout. Deux protocoles qui partagent la liquidité ou deux esprits qui synchronisent une thèse.\n\nTirée : The Strategic Partnership ({o}).\n\n"{quote}"\n\nClock-in du jour {streak}. Intention synchronisée on-chain.\n#Solana #ArkanaTarot #Seeker',
    bn: 'DeFi-তে তাল মেলানোই সব। দুটো প্রোটোকল লিকুইডিটি ভাগ করছে, বা দুটো মন একটা থিসিসে সুর মেলাচ্ছে।\n\nউঠল: The Strategic Partnership ({o})।\n\n"{quote}"\n\nদিন {streak}-এর ক্লক-ইন। অন-চেইনে অভিপ্রায়ের মিলন।\n#Solana #ArkanaTarot #Seeker',
    pt: 'Na DeFi, alinhamento é tudo. Dois protocolos dividindo liquidez ou duas mentes sincronizando uma tese.\n\nSaiu: The Strategic Partnership ({o}).\n\n"{quote}"\n\nClock-in do dia {streak}. Sincronizando a intenção on-chain.\n#Solana #ArkanaTarot #Seeker',
    ru: 'В DeFi согласованность решает всё. Два протокола делят ликвидность или два ума синхронизируют тезис.\n\nВытянута: The Strategic Partnership ({o}).\n\n"{quote}"\n\nДень {streak} отметки. Синхронизирую намерения ончейн.\n#Solana #ArkanaTarot #Seeker',
