    hi: 'प्रोटोकॉल और यूज़र के बीच आपसी लिक्विडिटी। जब इंसेंटिव मेल खाते हैं, यील्ड बिना शिकारी अनलॉक के सहज बहती है।\n\nआज की कंसेंसस: Yield Farming ({o}).\n\n"{quote}"\n\nSeeker पर स्ट्रीक का दिन {streak}.\n#Solana #ArkanaTarot #DeFi',
    es: 'Liquidez mutua entre protocolo y usuario. Cuando los incentivos se alinean, el rendimiento fluye sin unlocks depredadores.\n\nConsenso de hoy: Yield Farming ({o}).\n\n"{quote}"\n\nRacha de {streak} días en Seeker.\n#Solana #ArkanaTarot #DeFi',
    ar: 'سيولة متبادلة بين البروتوكول والمستخدم. حين تتوافق الحوافز، يتدفق العائد طبيعيًا بلا unlocks مفترسة.\n\nإجماع اليوم: Yield Farming ({o}).\n\n"{quote}"\n\nاليوم {streak} من السلسلة على Seeker.\n#Solana #ArkanaTarot #DeFi',
    fr: 'Liquidité mutuelle entre protocole et utilisateur. Quand les incitations s\'alignent, le rendement coule sans unlocks prédateurs.\n\nConsensus du jour : Yield Farming ({o}).\n\n"{quote}"\n\nSérie de {streak} jours sur Seeker.\n#Solana #ArkanaTarot #DeFi',
    bn: 'প্রোটোকল আর ইউজারের মধ্যে পারস্পরিক লিকুইডিটি। ইনসেনটিভ মিললে ইল্ড স্বাভাবিকভাবে বয়, শিকারি আনলক ছাড়াই।\n\nআজকের কনসেনসাস: Yield Farming ({o})।\n\n"{quote}"\n\nSeeker-এ স্ট্রিকের দিন {streak}।\n#Solana #ArkanaTarot #DeFi',
    pt: 'Liquidez mútua entre protocolo e usuário. Quando os incentivos se alinham, o rendimento flui sem unlocks predatórios.\n\nConsenso de hoje: Yield Farming ({o}).\n\n"{quote}"\n\nSequência de {streak} dias no Seeker.\n#Solana #ArkanaTarot #DeFi',
    ru: 'Взаимная ликвидность протокола и пользователя. Когда стимулы совпадают, доходность течёт сама, без хищных анлоков.\n\nКонсенсус дня: Yield Farming ({o}).\n\n"{quote}"\n\nДень {streak} серии на Seeker.\n#Solana #ArkanaTarot #DeFi',
    id: 'Likuiditas timbal balik antara protokol dan pengguna. Saat insentif selaras, yield mengalir alami tanpa unlock yang predator.\n\nKonsensus hari ini: Yield Farming ({o}).\n\n"{quote}"\n\nStreak hari ke-{streak} di Seeker.\n#Solana #ArkanaTarot #DeFi',
