    es: 'Comprar velas verdes a mercado con 10x porque el timeline estaba eufórico. Arkana advierte de velocidad sin dirección.\n\nAdvertencia del Altar: FOMO Chaser ({o}).\n\n"{quote}"\n\nDía {streak}. Bajo el ritmo de ejecución para salvar capital.\n#Solana #ArkanaTarot #Seeker',
