    fr: 'Acheter des bougies vertes au marché avec un levier x10 parce que la timeline était euphorique. Arkana met en garde contre la vitesse sans direction.\n\nAvertissement de l\'Autel : FOMO Chaser ({o}).\n\n"{quote}"\n\nJour {streak}. Je ralentis l\'exécution pour sauver mon capital.\n#Solana #ArkanaTarot #Seeker',
