    pt: 'Comprar vela verde a mercado com 10x porque a timeline estava eufórica. Arkana alerta: velocidade sem direção.\n\nAlerta do Altar: FOMO Chaser ({o}).\n\n"{quote}"\n\nDia {streak}. Desacelerando a execução para salvar capital.\n#Solana #ArkanaTarot #Seeker',
    ru: 'Покупать зелёные свечи по рынку с плечом 10x, потому что лента в эйфории. Arkana предупреждает о скорости без направления.\n\nПредупреждение Алтаря: FOMO Chaser ({o}).\n\n"{quote}"\n\nДень {streak}. Замедляю исполнение, чтобы сберечь капитал.\n#Solana #ArkanaTarot #Seeker',
