    hi: 'एक Genesis आर्कटाइप वेदी पर उतरा: #{no} {card} ({o}).\n\nकंसेंसस का संदेश: "{quote}"\n\nमाइक्रो शोर से ऊपर मैक्रो फ़्रीक्वेंसी। दिन {streak} की कंसेंसस @SolanaMobile पर सील।\n#Solana #ArkanaTarot #Seeker #ClockIn',
