    ar: 'نموذج Genesis حلّ على المذبح: #{no} {card} ({o}).\n\nبث الإجماع: "{quote}"\n\nتردد الماكرو فوق ضجيج الميكرو. إجماع اليوم {streak} مختوم على @SolanaMobile.\n#Solana #ArkanaTarot #Seeker #ClockIn',
