    bn: 'একটি Genesis আর্কিটাইপ নামল বেদিতে: #{no} {card} ({o})।\n\nকনসেনসাসের বার্তা: "{quote}"\n\nমাইক্রো গোলমালের ওপরে ম্যাক্রো ফ্রিকোয়েন্সি। দিন {streak}-এর কনসেনসাস @SolanaMobile-এ সিল করা হলো।\n#Solana #ArkanaTarot #Seeker #ClockIn',
